import math
from mpmath import betainc, findroot
def tcdf(t, df):
    x = df / (df + t * t)
    p = 0.5 * betainc(df / 2.0, 0.5, 0, x, regularized=True)
    return float(1 - p if t > 0 else p)
def tinv(p, df):
    return float(findroot(lambda t: tcdf(t, df) - p, 2.0))
def ncdf(z):
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))
def zstar(p):
    return float(findroot(lambda z: ncdf(z) - p, 1.5))
def welch(s1, n1, s2, n2):
    a = s1 * s1 / n1; b = s2 * s2 / n2
    return math.sqrt(a + b), (a + b) ** 2 / (a * a / (n1 - 1) + b * b / (n2 - 1))
n1, m1, s1, n2, m2, s2, conf = 32, 78.4, 11.2, 35, 72.1, 9.8, 0.95
df = min(n1 - 1, n2 - 1)
assert df == 31
ts = tinv(1 - (1 - conf) / 2, df)
assert abs(ts - 2.04) < 0.0006
for k, v in [(29, 2.045), (30, 2.042), (31, 2.04), (32, 2.037), (33, 2.035)]:
    assert abs(tinv(1 - (1 - conf) / 2, k) - v) < 0.0006
se = math.sqrt(s1 ** 2 / n1 + s2 ** 2 / n2)
assert round(se, 3) == 2.581
lo = (m1 - m2) - 2.04 * se; hi = (m1 - m2) + 2.04 * se
assert round(lo, 2) == 1.03 and round(hi, 2) == 11.57
se2, df2 = welch(s1, n1, s2, n2)
assert round(df2, 1) == 61.9
t2 = tinv(1 - (1 - conf) / 2, 61.9)
assert abs(t2 - 1.999) < 0.0006 and t2 < 2.04
assert round((m1 - m2) - 1.999 * se, 2) == 1.14 and round((m1 - m2) + 1.999 * se, 2) == 11.46
print("ALL_CHECKS_PASSED")

